SELECT , i.title AS item_title, i.cover_img AS item_cover, b.nickname AS buyer_name, s.nickname AS seller_name FROM tb_orders o
AND o.buyer_id = #{buyerId}
AND o.seller_id = #{sellerId}
AND o.status = #{status}
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR i.title LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY o.create_time DESC
